package com.example.rokidkeyboardbridge;
public class OffDutyRestTest {
 public static int n;static void ok(boolean v,String m){n++;if(!v)throw new AssertionError(m);}
 public static void main(String[] args){for(int pose=0;pose<4;pose++){String q=OffDutyPoseIntent.COMMANDS[pose];ok(ComfortPoseIntent.action(q)==pose+4,"command resolves new body");ok(ComfortPoseIntent.action("ロキ、"+q+"ください")==pose+4,"voice prefix");EmbodiedScenePolicy s=new EmbodiedScenePolicy();s.user(q,10000);ok(s.correctedRest()&&s.restMotion(10000)==12+pose&&s.posture()==0,"actual lying pose state");s.answer(ComfortPoseIntent.reply(pose+4),FullBodyPoseCatalog.Kind.NEUTRAL,11000);ok(s.restMotion(11000)==12+pose,"local acknowledgement preserves body");s.user("眠そうな顔にして",12000);ok(s.restMotion(12000)==12+pose&&s.restFace()==10&&s.restFacePinned(),"sleepy expression does not change body");s.user("考える顔にして",13000);ok(s.restFace()==7&&s.restMotion(13000)==12+pose,"thought expression keeps new pose");s.user("心配そうな顔にして",14000);ok(s.restFace()==7,"missing concern is not mapped to sleepy expression");s.user("表情をおまかせにして",15000);ok(!s.restFacePinned()&&s.restMotion(15000)==12+pose,"automatic expression maintains body");s.user("立って",16000);ok(!s.correctedRest(),"explicit exit works");}
 for(String q:new String[]{"彼女が枕を抱えて横になっている","枕を抱えて横になってほしくない","うつ伏せで頬杖をついてという例文","肘をついてだらっと休んでと言った","両手を頭の後ろに置いて休んで？"})ok(OffDutyPoseIntent.action(q)<0,"quote/negation/question excluded");
 for(int pose=4;pose<8;pose++){ok(ComfortPoseGeometry.ASSETS[pose].contains("v683"),"versioned asset");ok(ComfortPoseGeometry.scale(pose,480,240)*ComfortPoseGeometry.HEAD_WIDTH[pose]<=76.81f,"head display size stays comparable");for(int v=0;v<4;v++){int[] c=ComfortPoseGeometry.crop(pose,v);ok(c[0]>=0&&c[1]>=0&&c[0]+c[2]<=1024&&c[1]+c[3]<=1536,"face crop within atlas");}ok(ComfortPoseGeometry.expression(pose,10)==3,"explicit sleepy uses closed-eye face");ok(ComfortPoseGeometry.expression(pose,9)==2,"concern never selects sleepy eyes");}
 for(int seq=0;seq<14;seq++){int choice=NaturalPosePolicy.alternative(0,seq);ok(choice!=8&&choice!=11,"lying auto variety never sits up");}for(int base=12;base<=15;base++)for(int seq=0;seq<8;seq++){int choice=NaturalPosePolicy.alternative(base,seq);ok(choice>=12&&choice<=14&&choice!=base,"off-duty alternatives keep lying");}
 NaturalPosePolicy natural=new NaturalPosePolicy();natural.user("だらっとくつろいで",10000);ok(natural.select(15,40000,1,false,false,true,false)>=12,"casual instruction enables lying variety");natural.user("ポーズを固定して",41000);ok(natural.select(15,200000,0,false,false,true,false)==15&&!natural.active(),"fixed posture still wins");EmbodiedScenePolicy sleep=new EmbodiedScenePolicy();sleep.user(OffDutyPoseIntent.COMMANDS[3],10000);ok(sleep.restMotion(10000)==15&&sleep.restFace()==10,"nightmare uses closed worried face");sleep.user("身もだえして",11000);ok(sleep.restMotion(11000)==15&&sleep.moving(12000),"restless motion keeps body and is finite");sleep.user("身じろぎを止めて",13000);ok(!sleep.moving(13000),"stop preserves sleeping pose without motion");ok(OffDutyPoseIntent.unavailable("抱き枕を膝の間に挟んで横になって"),"unavailable image is explicit rather than pretending to perform it");
 System.out.println("PASS "+n+" off-duty rest, expression, anatomy-scale and continuity checks");}
}
